  "myspace.apps.favorites": "Избранное",
  "myspace.apps.noFavorites":
    "Избранного пока нет. Нажмите на сердечко на карточке, чтобы добавить.",
  "myspace.footer": "Меньше суеты. Больше пространства.",
  "myspace.translate.action": "Перевести",
  "myspace.translate.working": "Перевод…",
  "myspace.translate.downloading": "Загрузка языкового пакета ({p})",
  "myspace.translate.target": "Язык перевода",
  "myspace.translate.copy": "Копировать",
  "myspace.translate.local": "Переведено на вашем устройстве",
