  "headerWidgets.empty": "В шапке пока нет виджетов.",
  "headerWidgets.dropHint": "Карточку с доски можно перетащить прямо в шапку.",
  "headerWidgets.reorderHint": "Перемещайте клавишами со стрелками вверх и вниз",
