  "headerWidgets.desc.weather": "Погода сейчас и световой день; температура рядом со значком",
  "headerWidgets.desc.sticky": "Цветная стопка заметок, счётчик и + для быстрой заметки",
  "headerWidgets.desc.tibot-summary":
    "Мини-колода: передняя карта в тоне самой срочной заявки, рядом их число",
  "headerWidgets.desc.tibot-rhythm":
    "Мини-столбцы точек: просрочено · сегодня · завтра · неделя · позже; рядом просроченные",
  "headerWidgets.desc.tibot-intro": "Кольцо прогресса за год, рядом закрыто / всего",
  "headerWidgets.desc.tibot-rings":
    "Три цветных кольца (корзины; заполненная часть — доля просроченных), рядом — число назначенных вам и процент просроченных",
  "headerWidgets.full": "Шапка заполнена: не больше {n} виджетов",
